import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
lines=open('answer.xyz').read().splitlines()[2:]
els=[l.split()[0] for l in lines];p=np.array([[float(v) for v in l.split()[1:]] for l in lines])
fig=plt.figure(figsize=(11,9));ax=fig.add_subplot(projection='3d')
cs={'C':'#333333','H':'#bbbbbb','O':'red','N':'blue','Si':'orange','S':'yellow','P':'purple','F':'green','Rh':'teal'}
# covalent bonds from radii
rs={'C':.76,'H':.31,'O':.66,'N':.71,'Si':1.11,'S':1.05,'P':1.07,'F':.57,'Rh':1.42}
for i in range(len(p)):
 for j in range(i):
  d=np.linalg.norm(p[i]-p[j]);cut=rs[els[i]]+rs[els[j]]+.25
  if d<cut:
   ax.plot(*p[[i,j]].T,color='gray',alpha=.7,lw=1.5)
for i,(e,xyz) in enumerate(zip(els,p)):
 ax.scatter(*xyz,color=cs[e],s=80 if e!='H' else 15,depthshade=False)
 if e!='H' and e!='C':ax.text(*xyz,f'{e}{i}',fontsize=11)
ax.set_box_aspect((1,1,1));ax.view_init(elev=15,azim=-90);ax.set_xlabel('X');ax.set_ylabel('Y');ax.set_zlabel('Z');plt.tight_layout();plt.savefig('render.png',dpi=150)
